// Hand-authored demonstration baseline, NOT generated by an AI and NOT packaged
// into production Actors. It reads public table/card markup, never oracle files.
import { load } from 'cheerio';
import type { ExtractionContext, ExtractionOutcome, Venue } from '../src/contract.js';

export function extract(html: string, context: ExtractionContext): ExtractionOutcome {
  const $ = load(html);
  const evidence = (locator: string) => ({ source_url: context.source_url, snapshot_sha256: context.snapshot_sha256, locator });
  const missing = (locator: string): ExtractionOutcome => ({ status: 'unsupported', reason: 'missing_required_data', evidence: evidence(locator) });
  const rows: Venue[] = [];
  const table = $('table tbody tr');
  const cards = $('article');
  if (table.length === 0 && cards.length === 0) return { status: 'unsupported', reason: 'unsupported_format', evidence: evidence('document') };

  const elements = table.length > 0 ? table.toArray() : cards.toArray();
  for (const element of elements) {
    const row = $(element);
    const id = row.attr('id');
    const locator = id ? `#${id}` : 'document';
    let fields: string[];
    if (table.length > 0) {
      const cells = row.children('td');
      fields = [cells.eq(0).text(), cells.eq(1).text(), cells.eq(2).text(), cells.eq(4).text(), cells.eq(5).text()].map((value) => value.trim());
    } else {
      const read = (label: string): string => row.find('dt').filter((_, node) => $(node).text().trim() === label).next('dd').text().trim();
      fields = ['Venue ID', 'Capacity', 'Price', 'Availability', 'Step-free access'].map(read);
    }
    const [venueId, capacity, price, availability, stepFree] = fields;
    const times = row.find('time[datetime]').toArray().map((node) => $(node).attr('datetime'));
    const money = /^([A-Z]{3}) (\d+)\.(\d{2})$/.exec(price ?? '');
    if (!id || !venueId || !/^\d+$/.test(capacity ?? '') || !money || times.length !== 2 || !times[0] || !times[1]
      || !['Available', 'Unavailable'].includes(availability ?? '') || !['Yes', 'No'].includes(stepFree ?? '')) return missing(locator);
    rows.push({
      venue_id: venueId,
      capacity: Number(capacity),
      price: { currency: money[1]!, minor_units: Number(money[2]) * 100 + Number(money[3]) },
      window: { start: times[0], end: times[1] },
      availability: availability === 'Available' ? 'available' : 'unavailable',
      step_free: stepFree === 'Yes',
      evidence: evidence(locator),
    });
  }
  return { status: 'supported', venues: rows };
}
